<?php
declare(strict_types=1);
require_once __DIR__ . '/shared-components/auth.php';
$organiser=auth_require_verified_organiser(); $pdo=auth_db();
function mr_h(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$eventFilter=(int)($_GET['event_id']??0); $ratingFilter=(int)($_GET['rating']??0); $contactFilter=(string)($_GET['contact']??'');
try {
    $ev=$pdo->prepare('SELECT EventID,EventName FROM EVENTS WHERE OrganiserID=:id ORDER BY EventDate DESC'); $ev->execute([':id'=>(int)$organiser['UserID']]); $events=$ev->fetchAll(PDO::FETCH_ASSOC);
    $where=['e.OrganiserID=:organiser_id']; $params=[':organiser_id'=>(int)$organiser['UserID']];
    if($eventFilter>0) { $where[]='r.EventID=:event_id'; $params[':event_id']=$eventFilter; }
    if($ratingFilter>=1 && $ratingFilter<=5) { $where[]='r.Rating=:rating'; $params[':rating']=$ratingFilter; }
    if($contactFilter==='yes') $where[]='r.WantsContact=1'; elseif($contactFilter==='no') $where[]='r.WantsContact=0';
    $sql='SELECT r.ReviewID,r.Rating,r.Comment,r.Tags,r.WantsContact,r.ContactEmail,r.ReviewDate,e.EventName,u.FirstName,u.LastName FROM REVIEWS r JOIN EVENTS e ON e.EventID=r.EventID JOIN USERS u ON u.UserID=r.UserID WHERE '.implode(' AND ',$where).' ORDER BY r.ReviewDate DESC LIMIT 250';
    $stmt=$pdo->prepare($sql); $stmt->execute($params); $reviews=$stmt->fetchAll(PDO::FETCH_ASSOC);
    $sum=$pdo->prepare('SELECT COUNT(*) AS total, ROUND(AVG(r.Rating),2) AS average_rating, SUM(r.WantsContact=1) AS contact_requests FROM REVIEWS r JOIN EVENTS e ON e.EventID=r.EventID WHERE e.OrganiserID=:id'); $sum->execute([':id'=>(int)$organiser['UserID']]); $summary=$sum->fetch(PDO::FETCH_ASSOC) ?: [];
} catch(PDOException $e) { error_log('EventNest reviews query failed: '.$e->getMessage()); http_response_code(500); exit('Reviews could not be loaded.'); }
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage reviews | EventNest</title><link rel="stylesheet" href="assets/css/style.css"></head><body><main class="container"><h1>Reviews for your events</h1><section class="dashboard-cards"><article class="card"><h2>Total reviews</h2><p><?= (int)($summary['total']??0) ?></p></article><article class="card"><h2>Average rating</h2><p><?= $summary['average_rating']!==null ? mr_h($summary['average_rating']).' / 5' : 'No ratings yet' ?></p></article><article class="card"><h2>Contact requests</h2><p><?= (int)($summary['contact_requests']??0) ?></p></article></section><form method="get"><label for="event_id">Event</label><select id="event_id" name="event_id"><option value="0">All events</option><?php foreach($events as $event): ?><option value="<?= (int)$event['EventID'] ?>" <?= $eventFilter===(int)$event['EventID']?'selected':'' ?>><?= mr_h($event['EventName']) ?></option><?php endforeach; ?></select><label for="rating">Rating</label><select id="rating" name="rating"><option value="0">All ratings</option><?php for($i=1;$i<=5;$i++): ?><option value="<?= $i ?>" <?= $ratingFilter===$i?'selected':'' ?>><?= $i ?> star<?= $i===1?'':'s' ?></option><?php endfor; ?></select><label for="contact">Contact permission</label><select id="contact" name="contact"><option value="">All</option><option value="yes" <?= $contactFilter==='yes'?'selected':'' ?>>Yes</option><option value="no" <?= $contactFilter==='no'?'selected':'' ?>>No</option></select><button type="submit">Filter</button></form><h2>Review list</h2><?php if(!$reviews): ?><p>No reviews match these filters.</p><?php else: ?><div class="table-responsive"><table><thead><tr><th>Event</th><th>Attendee</th><th>Rating</th><th>Feedback</th><th>Contact permission</th><th>Contact email</th><th>Date</th></tr></thead><tbody><?php foreach($reviews as $r): ?><tr><td><?= mr_h($r['EventName']) ?></td><td><?= mr_h(trim($r['FirstName'].' '.$r['LastName'])) ?></td><td><?= (int)$r['Rating'] ?>/5</td><td><?= mr_h($r['Rating']>=4 ? ($r['Tags']??'') : ($r['Comment']??'')) ?></td><td><?= $r['WantsContact']?'Yes':'No' ?></td><td><?= $r['WantsContact']?mr_h($r['ContactEmail']??''):'—' ?></td><td><?= mr_h($r['ReviewDate']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p><a href="business-dashboard.php">Back to dashboard</a></p></main></body></html>
